			duration: 0,
			permitWait: Math.max(0, permittedAt - queuedAt),
			dispatchDuration: Math.max(0, startedAt - permittedAt),
			priority: Number.isFinite(details.priority) ? details.priority : null,
			recoveryProbe: details.recoveryProbe === true,
			attempt: Math.max(1, Math.floor(Number(details.attempt) || 1)),
			waitReason: String(details.waitReason || ''),
			callSite: details.callSite == null ? requestFlowCallSite() : String(details.callSite),
			type: details.type || requestFlowType(url, details.transport, details.method),
			path: String(details.path || requestFlowPath(url)),
			sameOrigin: !!url && url.origin === BASE,
			status: details.controlOnly ? 0 : null,
			size: 0,
