		const meta = init?.[REQUEST_FLOW_FETCH_META] || {};
		const startedAt = Number.isFinite(Number(meta.startedAt)) ? Number(meta.startedAt) : requestFlowNow();
		const queuedAt = Number.isFinite(Number(meta.queuedAt))
			? Math.min(startedAt, Math.max(startedAt - REQUEST_FLOW_RETENTION_MS, Number(meta.queuedAt)))
			: startedAt;
		const permittedAt = Number.isFinite(Number(meta.permittedAt))
			? Math.min(startedAt, Math.max(queuedAt, Number(meta.permittedAt)))
			: startedAt;
		const event = createRequestFlowEvent(url, {
			queuedAt,
			permittedAt,
			startedAt,
			endedAt: meta.endedAt,
			method,
			transport,
			source: meta.source === 'reader' ? 'reader' : 'host',
			priority: meta.priority,
			recoveryProbe: meta.recoveryProbe,
			attempt: meta.attempt,
			waitReason: meta.waitReason,
			callSite: meta.callSite,
			type: String(meta.type || requestFlowType(url, meta.classificationTransport || transport, method)),
			controlOnly: meta.controlOnly,
			controlReason: meta.controlReason,
			path: meta.path,
		});
		insertRequestFlowEvent(event);
		pruneRequestFlowEvents(event.startedAt);
		if (SHARED_REQUEST_COORDINATOR && !event.controlOnly) SHARED_REQUEST_COORDINATOR.recordHostStart(event);
		return event;
