	function recordRequestFlowControl(input, options = {}) {
		const endedAt = requestFlowNow();
		return beginRequestFlow(input, {
			method: options.method,
			[REQUEST_FLOW_FETCH_META]: {
				...options,
				source: 'reader',
				startedAt: endedAt,
				permittedAt: endedAt,
				endedAt,
				controlOnly: true,
				controlReason: options.controlReason || 'cancelled',
				classificationTransport: 'fetch',
			},
		}, 'scheduler');
	}

	const REQUEST_FLOW_RESPONSE_HEADERS = {
		rateLimitCode: ['Discourse-Rate-Limit-Error-Code', 'X-Discourse-Rate-Limit-Error-Code'],
		retryAfter: ['Retry-After'],
		serverLimit: ['RateLimit-Limit', 'X-RateLimit-Limit'],
		serverRemaining: ['RateLimit-Remaining', 'X-RateLimit-Remaining'],
		serverReset: ['RateLimit-Reset', 'X-RateLimit-Reset'],
	};

	function requestFlowHeader(headers, names, splitHeaders = null) {
		if (typeof headers === 'string') {
			const lines = splitHeaders || headers.split(/\r?\n/);
			for (const name of names) {
				const prefix = `${name.toLowerCase()}:`;
				const line = lines.find((candidate) => candidate.toLowerCase().startsWith(prefix));
				if (line) return line.slice(line.indexOf(':') + 1).trim();
			}
			return '';
		}
		if (!headers || !isFunction(headers.get)) return '';
		for (const name of names) {
			const value = headers.get(name);
			if (value != null && value !== '') return String(value);
		}
		return '';
	}

	function requestFlowRateLimitNumber(value) {
		const match = String(value == null ? '' : value).match(/-?\d+(?:\.\d+)?/);
		if (!match) return NaN;
		const number = Number(match[0]);
		return Number.isFinite(number) ? number : NaN;
	}

	function requestFlowRateLimitResetDelay(value, at = Date.now()) {
		const raw = String(value == null ? '' : value).trim();
		const number = Number(raw);
		if (!Number.isFinite(number)) {
			const resetAt = Date.parse(raw);
			return Number.isFinite(resetAt) ? Math.max(0, resetAt - at) : 0;
		}
		if (!(number > 0)) return 0;
		if (number > 1e12) return Math.max(0, number - at);
		if (number > at / 1000 - DAY / 1000) return Math.max(0, number * 1000 - at);
		return Math.max(0, number * 1000);
	}

	function rateLimitWindowFromCode(code) {
		const short = /10[_-]?(?:secs?|seconds?)/i.test(String(code || ''));
		const long = /60[_-]?(?:secs?|seconds?)|minute/i.test(String(code || ''));
		return {
			short, long, known: short || long,
			label: short && long ? '10s+60s' : short ? '10s' : long ? '60s' : 'unknown',
		};
	}

	function requestFlowRateLimitPolicies(event) {
		const rawLimit = String(event?.serverLimit || '');
		if (!rawLimit) return [];
		const remainingParts = String(event?.serverRemaining || '').split(',');
		const resetParts = String(event?.serverReset || '').split(',');
		const rateWindow = rateLimitWindowFromCode(event?.rateLimitCode);
		const byWindow = new Map();
		rawLimit.split(',').forEach((part, index) => {
			const limit = requestFlowRateLimitNumber(part);
			if (!(limit > 0)) return;
			const explicitWindow = String(part).match(/(?:^|;)\s*w\s*=\s*"?(\d+)/i);
			const windowSeconds = explicitWindow ? Number(explicitWindow[1]) : 0;
			const resetDelay = requestFlowRateLimitResetDelay(resetParts[index] || resetParts[0]);
			let window = windowSeconds > 0 && windowSeconds <= 15
				? '10s'
				: windowSeconds > 15 && windowSeconds <= 90
					? '60s'
					: '';
			if (explicitWindow && !window) return;
			if (!window) {
				const { short: hitShort, long: hitLong } = rateWindow;
				if (resetDelay > 90000 && !hitShort && !hitLong) return;
				window = hitShort && !hitLong
					? '10s'
					: hitLong && !hitShort
						? '60s'
						: limit <= READER_REQUEST_DEFAULT_SHORT_CEILING * 2
							? '10s'
							: '60s';
			}
			const policy = {
				window,
				limit,
				remaining: requestFlowRateLimitNumber(remainingParts[index] || (index === 0 ? remainingParts[0] : '')),
				resetDelay,
			};
			const previous = byWindow.get(window);
			if (!previous || policy.limit < previous.limit) byWindow.set(window, policy);
		});
		return [...byWindow.values()];
	}

	function finishRequestFlow(event, details = {}) {
		if (!event || !event.pending) return;
		event.endedAt = Number(details.endedAt) || requestFlowNow();
		if (!event.resourceTimed) {
			event.duration = Number.isFinite(Number(details.duration))
				? Math.max(0, Number(details.duration))
				: Math.max(0, event.endedAt - event.startedAt);
			event.size = Math.max(0, Number(details.size) || 0);
		}
		event.status = Number.isFinite(Number(details.status)) ? Number(details.status) : 0;
		event.pending = false;
		event.rateLimitCode = String(details.rateLimitCode || '');
		event.retryAfter = String(details.retryAfter || '');
		event.serverLimit = String(details.serverLimit || '');
		event.serverRemaining = String(details.serverRemaining || '');
		event.serverReset = String(details.serverReset || '');
		event.error = String(details.error || '');
		if (SHARED_REQUEST_COORDINATOR) SHARED_REQUEST_COORDINATOR.recordHostFinish(event);
		const hostApiEvent = sharedRequestApiEvent(event);
		const readerApiEvent = sharedRequestApiEvent(event, 'reader');
		const successfulApiEvent = (hostApiEvent || readerApiEvent) && event.status >= 200 && event.status < 400;
		let schedulerState = null;
		if (SHARED_REQUEST_COORDINATOR && (successfulApiEvent || (hostApiEvent && event.status === 429))) {
			try { schedulerState = ACTIVE_READER_REQUEST_SCHEDULER?.snapshot(); } catch {}
		}
		if (successfulApiEvent && SHARED_REQUEST_COORDINATOR && event.serverLimit) {
			SHARED_REQUEST_COORDINATOR.noteServerLimits({
				policies: requestFlowRateLimitPolicies(event),
				rateTarget: schedulerState ? schedulerState.requestRateTarget / 100 : 0.8,
				shortBudgetCap: schedulerState ? schedulerState.configuredShortWindowBudget : 40,
				longBudgetCap: schedulerState ? schedulerState.configuredLongWindowBudget : 160,
			});
		}
		if (successfulApiEvent && SHARED_REQUEST_COORDINATOR) {
			SHARED_REQUEST_COORDINATOR.noteSuccess({
				host: hostApiEvent,
				recoveryProbe: readerApiEvent && event.recoveryProbe,
				shortBudgetCap: schedulerState ? schedulerState.configuredShortWindowBudget : 40,
				longBudgetCap: schedulerState ? schedulerState.configuredLongWindowBudget : 160,
			});
		}
		if (hostApiEvent && event.status === 429 && SHARED_REQUEST_COORDINATOR) {
			const retrySeconds = event.retryAfter.trim() ? Number(event.retryAfter) : NaN;
			const retryDate = !Number.isFinite(retrySeconds) && event.retryAfter ? Date.parse(event.retryAfter) : 0;
			const wait = Number.isFinite(retrySeconds)
				? retrySeconds * 1000
				: retryDate
					? Math.max(0, retryDate - Date.now())
					: POST_REQUEST_429_BACKOFF;
			SHARED_REQUEST_COORDINATOR.noteRateLimit({
				wait: Math.max(1000, wait),
				window: rateLimitWindowFromCode(event.rateLimitCode).label,
				shortBudget: schedulerState ? schedulerState.shortWindowBudget : 40,
				longBudget: schedulerState ? schedulerState.longWindowBudget : 160,
			});
		}
	}

	function finishResponseRequestFlow(event, responseUrl, status, headers) {
		const finalUrl = requestFlowUrl(responseUrl);
		if (finalUrl) {
			event.path = requestFlowPath(finalUrl);
			event.sameOrigin = finalUrl.origin === BASE;
			if (event.type === 'other') {
				event.type = requestFlowType(finalUrl, event.transport, event.method);
			}
		}
		const splitHeaders = typeof headers === 'string' ? headers.split(/\r?\n/) : null;
		const contentLength = Number(requestFlowHeader(headers, ['Content-Length'], splitHeaders));
		finishRequestFlow(event, {
			status,
			size: Number.isFinite(contentLength) ? contentLength : 0,
			...Object.fromEntries(Object.entries(REQUEST_FLOW_RESPONSE_HEADERS).map(
				([key, names]) => [key, requestFlowHeader(headers, names, splitHeaders)]
			)),
		});
		return finalUrl;
	}

	function hostTopicResponseId(url) {
		if (!url || url.origin !== BASE) return 0;
		const match = url.pathname.match(/^\/t\/(?:[^/]+\/)?(\d+)(?:\/|\.json|$)/);
		return match ? Number(match[1]) : 0;
	}

	function storeHostTopicResponse(event, url, payload) {
		if (!event || event.source !== 'host' || event.method !== 'GET') return;
		const topicId = hostTopicResponseId(url);
		const postStream = payload?.post_stream;
		if (!topicId || Number(payload?.id) !== topicId || !postStream ||
			!Array.isArray(postStream.stream) || !Array.isArray(postStream.posts)) return;
		const key = String(topicId);
		const readerEntry = TOPIC_DATA_CACHE.get(key);
		if (readerEntry && readerEntry.scope === responseCacheAuthScope() &&
				topicCacheEntryTimestamp(readerEntry) >= Number(event.startedAt || 0)) return;
		const hostEntry = HOST_TOPIC_DATA_CACHE.get(key);
		if (hostEntry && Number(hostEntry.startedAt || 0) > event.startedAt) return;
		HOST_TOPIC_DATA_CACHE.delete(key);
		HOST_TOPIC_DATA_CACHE.set(key, { topic: payload, at: Date.now(), startedAt: event.startedAt });
		setCachedTopicData(topicId, payload, { fetchedAt: Date.now(), source: 'host' });
		while (HOST_TOPIC_DATA_CACHE.size > HOST_TOPIC_CACHE_MAX_ENTRIES) {
			HOST_TOPIC_DATA_CACHE.delete(HOST_TOPIC_DATA_CACHE.keys().next().value);
		}
	}

	function captureHostTopicXhrResponse(event, xhr, url) {
		if (!xhr || event.source !== 'host' || event.method !== 'GET' || xhr.status < 200 || xhr.status >= 300 ||
			!hostTopicResponseId(url)) return;
		try {
			const contentType = String(xhr.getResponseHeader('Content-Type') || '').toLowerCase();
			if (!contentType.includes('json')) return;
			const payload = xhr.responseType === 'json' ? xhr.response : JSON.parse(xhr.responseText);
			storeHostTopicResponse(event, url, payload);
		} catch {}
	}

	function recordResourceRequestFlow(entry) {
		const initiator = String(entry?.initiatorType || '').toLowerCase();
		if (!entry) return;
		const url = requestFlowUrl(entry.name);
		if (!url || !['http:', 'https:'].includes(url.protocol)) return;
		const startedAt = performance.timeOrigin + Number(entry.startTime || 0);
		const duration = Math.max(0, Number(entry.duration) || 0);
		const size = Math.max(0, Number(entry.transferSize || entry.encodedBodySize) || 0);
		const path = requestFlowPath(url);
		if (['fetch', 'xmlhttprequest'].includes(initiator)) {
			let matchingRequest = null;
			for (let index = requestFlowEventIndex(startedAt - 100); index < REQUEST_FLOW_EVENTS.length; index++) {
				const event = REQUEST_FLOW_EVENTS[index];
				const eventStartedAt = Number(event.startedAt);
				if (eventStartedAt > startedAt + 100) break;
				if (!Number.isFinite(eventStartedAt) || event.controlOnly || event.resourceTimed ||
						event.transport !== initiator || event.path !== path) continue;
				if (!matchingRequest || Math.abs(eventStartedAt - startedAt) < Math.abs(matchingRequest.startedAt - startedAt)) {
					matchingRequest = event;
				}
			}
			if (matchingRequest) {
				Object.assign(matchingRequest, { resourceTimed: true, duration, size });
				return;
			}
		}
		const event = createRequestFlowEvent(url, {
			queuedAt: startedAt,
			permittedAt: startedAt,
			startedAt,
			method: 'GET',
			transport: initiator || 'resource',
			source: 'browser',
			priority: null,
			callSite: initiator ? `${initiator} 资源加载` : '浏览器资源加载',
			type: requestFlowType(url, initiator, 'GET'),
			path,
		});
		finishRequestFlow(event, {
			endedAt: performance.timeOrigin + Number(entry.responseEnd || entry.startTime || 0),
			duration,
			status: Number(entry.responseStatus) || 0,
			size,
		});
		event.resourceTimed = true;
		insertRequestFlowEvent(event);
	}

	const SHARED_REQUEST_API_TRANSPORTS = Object.freeze({ host: ['fetch', 'xmlhttprequest'], reader: ['fetch'] });
	function sharedRequestApiEvent(event, source = 'host') {
		return !!event && event.source === source && event.sameOrigin === true &&
			SHARED_REQUEST_API_TRANSPORTS[source]?.includes(event.transport) === true &&
			!['avatar', 'media', 'asset', 'realtime'].includes(event.type);
	}

	function createSharedRequestCoordinator() {
		const contextId = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
		const lockName = `${LDP_SHARED_REQUEST_CHANNEL}:lock`;
		const cacheLockName = `${LDP_SHARED_REQUEST_CHANNEL}:cache-lock`;
		const waiters = new Set();
		const cacheListeners = new Set();
		let sequence = 0;
		let destroyed = false;
		let channel = null;

		const emptyState = () => ({
			version: 2,
			updatedAt: 0,
			events: [],
			intents: [],
			active: [],
			policies: [],
			flights: [],
			cacheEpoch: 0,
			shortBudget: 0,
			longBudget: 0,
			shortServerBudget: 0,
			longServerBudget: 0,
			cooldownUntil: 0,
			nextProbeAt: 0,
			shortServerBlockUntil: 0,
			longServerBlockUntil: 0,
			rateLimited: false,
			successfulSinceLimit: 0,
			lastRateLimitWindow: '',
			learnedUntil: 0,
		});

		const requestPolicy = (source = {}, policyContextId = contextId) => ({
			contextId: String(policyContextId),
			shortBudget: Math.max(1, Math.floor(Number(source.shortBudget) || READER_REQUEST_DEFAULT_SHORT_CEILING)),
			longBudget: Math.max(1, Math.floor(Number(source.longBudget) || READER_REQUEST_DEFAULT_LONG_CEILING)),
			minInterval: Math.max(0, Math.floor(Number(source.minInterval) || 0)),
			maxConcurrent: Math.max(1, Math.floor(Number(source.maxConcurrent) || 1)),
		});

		const normalizeState = (raw, at = Date.now()) => {
			const state = raw && typeof raw === 'object' ? raw : emptyState();
			state.version = 2;
			state.events = (Array.isArray(state.events) ? state.events : [])
				.map((event) => ({ at: Number(event?.at) || 0 }))
				.filter((event) => event.at > at - READER_REQUEST_LONG_WINDOW_MS && event.at <= at)
				.sort((a, b) => a.at - b.at)
				.slice(-600);
			state.intents = (Array.isArray(state.intents) ? state.intents : [])
				.filter((intent) => intent && Number(intent.expiresAt) > at)
				.slice(-120);
			state.active = (Array.isArray(state.active) ? state.active : [])
				.filter((lease) => lease && Number(lease.expiresAt) > at)
				.slice(-32);
			state.policies = (Array.isArray(state.policies) ? state.policies : [])
				.filter((policy) => policy?.contextId && Number(policy.expiresAt) > at)
				.map((policy) => ({
					...requestPolicy(policy, policy.contextId),
					expiresAt: Number(policy.expiresAt),
				}))
				.slice(-32);
			state.flights = (Array.isArray(state.flights) ? state.flights : [])
				.map((flight) => ({
					...flight,
					heartbeatAt: Number(flight?.heartbeatAt) ||
						Math.max(0, Number(flight?.expiresAt) - SHARED_CACHE_FLIGHT_TTL),
				}))
				.filter((flight) => flight?.token && Number(flight.expiresAt) > at &&
					Number(flight.heartbeatAt) > at - SHARED_CACHE_FLIGHT_STALE_MS)
				.sort((a, b) => Number(a.expiresAt) - Number(b.expiresAt))
				.slice(-120);
			state.cacheEpoch = Math.max(0, Math.floor(Number(state.cacheEpoch) || 0));
			state.shortBudget = Math.max(0, Number(state.shortBudget) || 0);
			state.longBudget = Math.max(0, Number(state.longBudget) || 0);
			state.shortServerBudget = Math.max(0, Number(state.shortServerBudget) || 0);
			state.longServerBudget = Math.max(0, Number(state.longServerBudget) || 0);
			state.cooldownUntil = Math.max(0, Number(state.cooldownUntil) || 0);
			state.nextProbeAt = Math.max(0, Number(state.nextProbeAt) || 0);
			state.shortServerBlockUntil = Math.max(0, Number(state.shortServerBlockUntil) || 0);
			state.longServerBlockUntil = Math.max(0, Number(state.longServerBlockUntil) || 0);
			state.successfulSinceLimit = Math.max(0, Number(state.successfulSinceLimit) || 0);
			state.lastRateLimitWindow = String(state.lastRateLimitWindow || '');
			state.learnedUntil = Math.max(0, Number(state.learnedUntil) || 0);
			if (state.learnedUntil <= at) {
				state.shortBudget = 0;
				state.longBudget = 0;
				state.shortServerBudget = 0;
				state.longServerBudget = 0;
				state.rateLimited = false;
				state.successfulSinceLimit = 0;
				state.lastRateLimitWindow = '';
			} else state.rateLimited = state.rateLimited === true;
			return state;
		};

		const readState = (at = Date.now()) => {
			try {
				return normalizeState(JSON.parse(localStorage.getItem(LDP_SHARED_REQUEST_STATE_KEY) || 'null'), at);
			} catch {
				return emptyState();
			}
		};

		const notifyWaiters = () => {
			waiters.forEach((resolve) => resolve());
			waiters.clear();
		};

		const transact = async (operation) => {
			const execute = () => {
				const at = Date.now();
				const state = readState(at);
				const result = operation(state, at);
				state.updatedAt = at;
				try { localStorage.setItem(LDP_SHARED_REQUEST_STATE_KEY, JSON.stringify(state)); } catch {}
				try { if (channel) channel.postMessage({ type: 'updated', contextId }); } catch {}
				notifyWaiters();
				return result;
			};
			const locks = navigator.locks;
			if (isFunction(locks?.request)) {
				return locks.request(lockName, { mode: 'exclusive' }, execute);
			}
			return execute();
		};

		const withCacheLock = (operation) => {
			const locks = navigator.locks;
			if (isFunction(locks?.request)) {
				return locks.request(cacheLockName, { mode: 'exclusive' }, operation);
			}
			return Promise.resolve().then(operation);
		};

		const windowState = (state, at, requestedShortBudget, requestedLongBudget) => {
			const shortBudget = Math.max(1, Math.floor(Math.min(
				requestedShortBudget,
				state.shortBudget || requestedShortBudget,
				state.shortServerBudget || requestedShortBudget
			)));
			const longBudget = Math.max(1, Math.floor(Math.min(
				requestedLongBudget,
				state.longBudget || requestedLongBudget,
				state.longServerBudget || requestedLongBudget
			)));
			const shortEvents = state.events.filter((event) => event.at > at - READER_REQUEST_SHORT_WINDOW_MS);
			const longEvents = state.events;
			const delayFor = (events, budget, windowMs) => events.length < budget
				? 0
				: Math.max(0, events[events.length - budget].at + windowMs - at + 1);
			const shortDelay = delayFor(shortEvents, shortBudget, READER_REQUEST_SHORT_WINDOW_MS);
			const longDelay = delayFor(longEvents, longBudget, READER_REQUEST_LONG_WINDOW_MS);
			const shortServerDelay = Math.max(0, state.shortServerBlockUntil - at);
			const longServerDelay = Math.max(0, state.longServerBlockUntil - at);
			const effectiveShortDelay = Math.max(shortDelay, shortServerDelay);
			const effectiveLongDelay = Math.max(longDelay, longServerDelay);
			return {
				shortCount: shortEvents.length,
				longCount: longEvents.length,
				shortBudget,
				longBudget,
				serverDelay: Math.max(shortServerDelay, longServerDelay),
				delay: Math.max(effectiveShortDelay, effectiveLongDelay),
				blockingWindow: effectiveShortDelay >= effectiveLongDelay && effectiveShortDelay
					? '10s'
					: effectiveLongDelay
						? '60s'
						: '',
			};
		};

		const permitTiming = (state, at, policy) => {
			const windows = windowState(state, at, policy.shortBudget, policy.longBudget);
			const cooldownDelay = Math.max(0, state.cooldownUntil - at);
			const latestStart = state.events.length ? Number(state.events[state.events.length - 1].at) || 0 : 0;
			return { windows, cooldownDelay, intervalDelay: Math.max(0, latestStart + policy.minInterval - at) };
		};

		const rememberPolicy = (state, at, options = {}) => {
			const policy = { ...requestPolicy(options), expiresAt: at + SHARED_REQUEST_POLICY_TTL };
			const index = state.policies.findIndex((candidate) => candidate.contextId === contextId);
			if (index >= 0) state.policies[index] = policy;
			else state.policies.push(policy);
			return policy;
		};

		const effectivePolicy = (state, ownPolicy) => {
			const effective = {
				shortBudget: ownPolicy.shortBudget,
				longBudget: ownPolicy.longBudget,
				minInterval: ownPolicy.minInterval,
				maxConcurrent: Math.min(state.rateLimited ? 2 : Infinity, ownPolicy.maxConcurrent),
			};
			state.policies.forEach((policy) => {
				if (policy.contextId === contextId) return;
				effective.shortBudget = Math.min(effective.shortBudget, policy.shortBudget);
				effective.longBudget = Math.min(effective.longBudget, policy.longBudget);
				effective.minInterval = Math.max(effective.minInterval, policy.minInterval);
				effective.maxConcurrent = Math.min(effective.maxConcurrent, policy.maxConcurrent);
			});
			return effective;
		};

		const intentPriority = (intent, at) => {
			const ageBoost = Math.min(2, Math.floor(Math.max(0, at - intent.queuedAt) / 5000));
			return Number(intent.priority) - ageBoost;
		};

		const waitForUpdate = (delay, signal) => new Promise((resolve, reject) => {
			let settled = false;
			const settle = (callback) => {
				if (settled) return;
				settled = true;
				clearTimeout(timer);
				waiters.delete(finish);
				if (signal) signal.removeEventListener('abort', abort);
				callback();
			};
			const finish = () => settle(resolve);
			const abort = () => settle(() => reject(new DOMException('Aborted', 'AbortError')));
			const timer = setTimeout(finish, Math.max(25, Math.min(1000, delay || 80)));
			waiters.add(finish);
			if (signal) signal.addEventListener('abort', abort, { once: true });
		});

		const cancelIntent = (intentId) => {
			void transact((state) => {
				state.intents = state.intents.filter((intent) => intent.id !== intentId);
			});
		};

		const acquirePermit = async (options = {}) => {
			const intentId = `${contextId}:intent:${++sequence}`;
			const priority = Number.isFinite(options.priority) ? options.priority : POST_REQUEST_PRIORITY.visible;
			const signal = options.signal;
			let granted = false;
			let waitReason = '';
			try {
				while (!destroyed && !(signal?.aborted)) {
					const result = await transact((state, at) => {
						const ownPolicy = rememberPolicy(state, at, options);
						const policy = effectivePolicy(state, ownPolicy);
						const existing = state.intents.find((intent) => intent.id === intentId);
						if (existing) existing.expiresAt = at + 15000;
						else state.intents.push({
							id: intentId,
							contextId,
							priority,
							queuedAt: at,
							expiresAt: at + 15000,
						});
						state.intents.sort((a, b) => intentPriority(a, at) - intentPriority(b, at) || a.queuedAt - b.queuedAt);
						if (!state.intents.length || state.intents[0].id !== intentId) {
							return { granted: false, wait: 80, reason: 'priority' };
						}
						if (state.active.length >= policy.maxConcurrent) {
							return { granted: false, wait: 80, reason: 'concurrency' };
						}
						const { windows, cooldownDelay, intervalDelay } = permitTiming(state, at, policy);
						const canProbe = state.rateLimited && !cooldownDelay && !windows.serverDelay && windows.delay > 0 &&
							!intervalDelay && priority <= POST_REQUEST_PRIORITY.visible && at >= state.nextProbeAt;
						const wait = Math.max(cooldownDelay, intervalDelay, canProbe ? 0 : windows.delay);
						if (wait > 0) {
							return {
								granted: false,
								wait,
								reason: cooldownDelay ? 'cooldown' : intervalDelay ? 'interval' : windows.blockingWindow,
							};
						}
						state.intents.shift();
						if (canProbe) state.nextProbeAt = at + READER_REQUEST_RECOVERY_PROBE_INTERVAL;
						state.events.push({ at });
						const permitId = `${contextId}:permit:${++sequence}`;
						state.active.push({ id: permitId, contextId, expiresAt: at + POST_REQUEST_TIMEOUT + 5000 });
						return { granted: true, permitId, startedAt: at, recoveryProbe: canProbe };
					});
					if (result.granted) {
						granted = true;
						return { ...result, waitReason };
					}
					if (result.cancelled) {
						waitReason = String(result.reason || waitReason || 'cancelled');
						throw new DOMException(waitReason, 'AbortError');
					}
					waitReason = String(result.reason || waitReason);
					await waitForUpdate(result.wait, signal);
				}
				throw new DOMException('Aborted', 'AbortError');
			} finally {
				if (!granted) cancelIntent(intentId);
			}
		};

		const recordHostStart = (event) => {
			if (!sharedRequestApiEvent(event) || destroyed) return;
			const activeId = `${contextId}:host-active:${event.id}`;
			event.sharedRequestActiveId = activeId;
			event.sharedRequestStart = transact((state, at) => {
				const startedAt = Math.max(at - 5000, Math.min(at, Number(event.startedAt) || at));
				state.events.push({ at: startedAt });
				state.active.push({ id: activeId, contextId, expiresAt: at + POST_REQUEST_TIMEOUT + 5000 });
			});
		};

		const finishPermit = (permitId) => {
			if (!permitId) return;
			void transact((state) => {
				state.active = state.active.filter((lease) => lease.id !== permitId);
			});
		};

		const recordHostFinish = (event) => {
			if (!event || !event.sharedRequestActiveId) return;
			Promise.resolve(event.sharedRequestStart).catch(() => {}).then(() => {
				finishPermit(event.sharedRequestActiveId);
			});
		};

		const acquireCacheFlight = (token) => transact((state, at) => {
			const normalizedToken = String(token || '');
			if (!normalizedToken) return { producer: true, flightId: '' };
			const existing = state.flights.find((flight) => flight.token === normalizedToken);
			if (existing) {
				return {
					producer: false,
					flightId: existing.id,
					expiresAt: existing.expiresAt,
					cacheEpoch: Number(existing.cacheEpoch) || 0,
				};
			}
			const flightId = `${contextId}:flight:${++sequence}`;
			state.flights.push({
				id: flightId,
				token: normalizedToken,
				contextId,
				cacheEpoch: state.cacheEpoch,
				heartbeatAt: at,
				expiresAt: at + SHARED_CACHE_FLIGHT_TTL,
			});
			return {
				producer: true,
				flightId,
				expiresAt: at + SHARED_CACHE_FLIGHT_TTL,
				cacheEpoch: state.cacheEpoch,
			};
		});

		const releaseCacheFlight = (token, flightId) => {
			if (!token || !flightId) return Promise.resolve();
			return transact((state) => {
				state.flights = state.flights.filter((flight) =>
					flight.token !== String(token) || flight.id !== String(flightId));
			});
		};

		const renewCacheFlight = (token, flightId) => {
			if (!token || !flightId) return Promise.resolve(false);
			return transact((state, at) => {
				const flight = state.flights.find((candidate) =>
					candidate.token === String(token) && candidate.id === String(flightId));
				if (!flight) return false;
				flight.heartbeatAt = at;
				flight.expiresAt = at + SHARED_CACHE_FLIGHT_TTL;
				return true;
			});
		};

		const writeCacheFlight = (token, flightId, cacheEpoch, operation) => withCacheLock(async () => {
			const state = readState();
			const valid = state.cacheEpoch === Number(cacheEpoch || 0) && state.flights.some((flight) =>
				flight.token === String(token) && flight.id === String(flightId));
			if (!valid) return false;
			await operation();
			return true;
		});

		const invalidateCacheWrites = () => withCacheLock(() => transact((state) => {
			state.cacheEpoch++;
			return state.cacheEpoch;
		}));

		const waitForCacheFlight = async (token, signal, deadline = Date.now() + SHARED_CACHE_FLIGHT_TTL) => {
			const normalizedToken = String(token || '');
			while (!destroyed && Date.now() < deadline && !(signal?.aborted)) {
				const state = readState();
				const flight = state.flights.find((candidate) => candidate.token === normalizedToken);
				if (!flight) return true;
				await waitForUpdate(Math.min(1000, Math.max(25, flight.expiresAt - Date.now())), signal);
			}
			if (signal?.aborted) throw new DOMException('Aborted', 'AbortError');
			return false;
		};

		const noteRateLimit = (options = {}) => {
			void transact((state, at) => {
				const windows = windowState(state, at, options.shortBudget, options.longBudget);
				const limitWindow = String(options.window || 'unknown');
				const hitShort = limitWindow === 'unknown' || limitWindow.includes('10s');
				const hitLong = limitWindow === 'unknown' || limitWindow.includes('60s');
				if (hitShort) {
					const safe = Math.max(1, Math.ceil(windows.shortCount * 0.9));
					state.shortBudget = state.shortBudget ? Math.min(state.shortBudget, safe) : safe;
				}
				if (hitLong) {
					const safe = Math.max(1, Math.ceil(windows.longCount * 0.9));
					state.longBudget = state.longBudget ? Math.min(state.longBudget, safe) : safe;
				}
				state.cooldownUntil = Math.max(state.cooldownUntil, at + Math.max(1000, Number(options.wait) || 0));
				state.nextProbeAt = state.cooldownUntil;
				state.rateLimited = true;
				state.successfulSinceLimit = 0;
				state.lastRateLimitWindow = limitWindow;
				state.learnedUntil = at + READER_REQUEST_RATE_MEMORY_TTL;
			});
		};

		const resetRateLimits = () => transact((state) => {
				[
					'shortBudget',
					'longBudget',
					'shortServerBudget',
					'longServerBudget',
					'cooldownUntil',
					'nextProbeAt',
					'shortServerBlockUntil',
					'longServerBlockUntil',
					'successfulSinceLimit',
					'learnedUntil',
				].forEach((key) => { state[key] = 0; });
				state.rateLimited = false;
				state.lastRateLimitWindow = '';
				return true;
			});

		const noteServerLimits = (options = {}) => {
			const rateTarget = Math.min(0.95, Math.max(0.5, Number(options.rateTarget) || 0.8));
			const shortCap = Math.max(1, Math.floor(Number(options.shortBudgetCap) || 40));
			const longCap = Math.max(1, Math.floor(Number(options.longBudgetCap) || 160));
			const policies = (Array.isArray(options.policies) ? options.policies : []).map((policy) => {
				const window = policy && policy.window === '10s' ? '10s' : policy && policy.window === '60s' ? '60s' : '';
				const limit = Math.max(0, Number(policy?.limit) || 0);
				const cap = window === '10s' ? shortCap : longCap;
				return {
					window,
					limit,
					remaining: Number(policy?.remaining),
					resetDelay: Math.max(0, Number(policy?.resetDelay) || 0),
					cap,
					desired: Math.max(1, Math.min(cap, Math.floor(limit * rateTarget))),
				};
			}).filter((policy) => policy.window && policy.limit > 0);
			if (!policies.length) return;
			const previewAt = Date.now();
			const preview = readState(previewAt);
			const needsUpdate = policies.some((policy) => {
				const budgetKey = policy.window === '10s' ? 'shortServerBudget' : 'longServerBudget';
				const blockKey = policy.window === '10s' ? 'shortServerBlockUntil' : 'longServerBlockUntil';
				const current = Number(preview[budgetKey]) || 0;
				const effective = current || policy.cap;
				const budgetChanges = policy.desired < effective ||
					(!preview.rateLimited && current > 0 && policy.desired > current);
				const reserve = Math.max(1, Math.ceil(policy.limit * (1 - rateTarget)));
				const shouldBlock = Number.isFinite(policy.remaining) && policy.remaining <= reserve && policy.resetDelay > 0;
				const blockUntil = shouldBlock ? previewAt + policy.resetDelay : 0;
				const blockChanges = shouldBlock
					? blockUntil > Number(preview[blockKey] || 0) + 500
					: Number(preview[blockKey] || 0) > previewAt;
				return budgetChanges || blockChanges;
			});
			if (!needsUpdate) return;
			void transact((state, at) => {
				let changed = false;
				policies.forEach((policy) => {
					const budgetKey = policy.window === '10s' ? 'shortServerBudget' : 'longServerBudget';
					const blockKey = policy.window === '10s' ? 'shortServerBlockUntil' : 'longServerBlockUntil';
					const windowMs = policy.window === '10s' ? READER_REQUEST_SHORT_WINDOW_MS : READER_REQUEST_LONG_WINDOW_MS;
					const current = Number(state[budgetKey]) || 0;
					if (!current && policy.desired < policy.cap) {
						state[budgetKey] = policy.desired;
						changed = true;
					} else if (current && policy.desired < current) {
						state[budgetKey] = policy.desired;
						changed = true;
					} else if (!state.rateLimited && current && policy.desired > current) {
						const step = Math.max(1, Math.ceil((policy.desired - current) * 0.35));
						const next = Math.min(policy.desired, current + step);
						state[budgetKey] = next >= policy.cap && policy.desired >= policy.cap ? 0 : next;
						changed = true;
					}
					const reserve = Math.max(1, Math.ceil(policy.limit * (1 - rateTarget)));
					const shouldBlock = Number.isFinite(policy.remaining) && policy.remaining <= reserve && policy.resetDelay > 0;
					if (shouldBlock) {
						const blockUntil = at + Math.min(windowMs + 1000, policy.resetDelay);
						if (blockUntil > Number(state[blockKey] || 0) + 500) {
							state[blockKey] = blockUntil;
							changed = true;
						}
					} else if (Number(state[blockKey] || 0) > at) {
						state[blockKey] = 0;
						changed = true;
					}
				});
				if (changed) state.learnedUntil = Math.max(state.learnedUntil, at + READER_REQUEST_RATE_MEMORY_TTL);
			});
		};

		const noteSuccess = (options = {}) => {
			const preview = readState();
			if (!preview.rateLimited && !preview.shortBudget && !preview.longBudget) return;
			void transact((state, at) => {
				if (at < state.cooldownUntil || (!state.shortBudget && !state.longBudget)) return;
				const credit = options.recoveryProbe ? 2 : options.host ? 0.5 : 1;
				state.successfulSinceLimit += credit;
				const shouldGrow = state.rateLimited ||
					state.successfulSinceLimit >= READER_REQUEST_RATE_PROBE_SUCCESSES;
				if (!shouldGrow) return;
				const shortCap = Math.max(1, Number(options.shortBudgetCap) || READER_REQUEST_DEFAULT_SHORT_CEILING);
				const longCap = Math.max(1, Number(options.longBudgetCap) || READER_REQUEST_DEFAULT_LONG_CEILING);
				const rateStep = options.recoveryProbe ? READER_REQUEST_PROBE_RATE_STEP : 1.04;
				if (state.shortBudget) {
					state.shortBudget = Math.min(
						shortCap,
						Math.max(state.shortBudget * rateStep, state.shortBudget + (options.recoveryProbe ? 2 : 1))
					);
				}
				if (state.longBudget) {
					state.longBudget = Math.min(
						longCap,
						Math.max(state.longBudget * rateStep, state.longBudget + (options.recoveryProbe ? 6 : 3))
					);
				}
				if (state.successfulSinceLimit >= READER_REQUEST_CONCURRENCY_RECOVERY_SUCCESSES) {
					state.rateLimited = false;
					state.successfulSinceLimit = 0;
				} else if (!state.rateLimited) {
					state.successfulSinceLimit = 0;
				}
				const shortRecovered = !state.shortBudget || state.shortBudget >= shortCap;
				const longRecovered = !state.longBudget || state.longBudget >= longCap;
				if (!state.rateLimited && shortRecovered && longRecovered) {
					state.shortBudget = 0;
					state.longBudget = 0;
				}
				state.learnedUntil = at + READER_REQUEST_RATE_MEMORY_TTL;
			});
		};

		const snapshot = (
			requestedShortBudget,
			requestedLongBudget,
			requestedMinInterval = 0,
			requestedMaxConcurrent = 1,
			at = Date.now()
		) => {
			const state = readState(at);
			const policy = effectivePolicy(state, requestPolicy({
				shortBudget: requestedShortBudget,
				longBudget: requestedLongBudget,
				minInterval: requestedMinInterval,
				maxConcurrent: requestedMaxConcurrent,
			}));
			const { windows, cooldownDelay: cooldownRemaining, intervalDelay } = permitTiming(state, at, policy);
			const nextPermitDelay = Math.max(cooldownRemaining, intervalDelay, windows.delay);
			const liveContexts = new Set([
				...state.policies.map((entry) => entry.contextId),
				...state.intents.map((entry) => entry.contextId),
				...state.active.map((entry) => entry.contextId),
			].filter(Boolean));
			return {
				...windows,
				queued: state.intents.length,
				active: state.active.length,
				instances: Math.max(1, liveContexts.size),
				maxConcurrent: policy.maxConcurrent,
				minInterval: policy.minInterval,
				coordinationMode: isFunction(navigator.locks?.request)
					? 'atomic'
					: 'best-effort',
				coolingDown: cooldownRemaining > 0,
				cooldownRemaining,
				nextPermitDelay,
				blockingReason: cooldownRemaining ? 'cooldown' : intervalDelay ? 'interval' : windows.blockingWindow,
				rateLimited: state.rateLimited,
				lastRateLimitWindow: state.lastRateLimitWindow,
			};
		};

		const onStorage = (event) => {
			if (event.key === LDP_SHARED_REQUEST_STATE_KEY) notifyWaiters();
		};
		const publishCache = (message) => {
			try {
				if (channel) channel.postMessage({ type: 'cache', contextId, message });
			} catch {}
		};
		const onChannelMessage = (event) => {
			const data = event?.data;
			if (data && data.type === 'cache' && data.contextId !== contextId)
				cacheListeners.forEach((listener) => {
					try { listener(data.message || {}); } catch {}
				});
			notifyWaiters();
		};
		try {
			channel = new globalThis.BroadcastChannel(LDP_SHARED_REQUEST_CHANNEL);
			channel.addEventListener('message', onChannelMessage);
		} catch {}
		window.addEventListener('storage', onStorage);

		return {
			contextId,
			acquirePermit,
			recordHostStart,
			recordHostFinish,
			finishPermit,
			acquireCacheFlight,
			releaseCacheFlight,
			renewCacheFlight,
			writeCacheFlight,
			invalidateCacheWrites,
			waitForCacheFlight,
			noteRateLimit,
			resetRateLimits,
			noteServerLimits,
			noteSuccess,
			snapshot,
			publishCache,
			subscribeCache(listener) {
				if (!isFunction(listener)) return () => {};
				cacheListeners.add(listener);
				return () => cacheListeners.delete(listener);
			},
			destroy() {
				if (destroyed) return;
				destroyed = true;
				void transact((state) => {
					state.intents = state.intents.filter((intent) => intent.contextId !== contextId);
					state.active = state.active.filter((lease) => lease.contextId !== contextId);
					state.policies = state.policies.filter((policy) => policy.contextId !== contextId);
					state.flights = state.flights.filter((flight) => flight.contextId !== contextId);
				});
				window.removeEventListener('storage', onStorage);
				if (channel) channel.close();
				channel = null;
				cacheListeners.clear();
				notifyWaiters();
			},
		};
	}

	function installRequestFlowInstrumentation() {
		if (!REQUEST_FLOW_AJAX_BOUND) {
			const jqueryModule = lookupDiscourseModule('jquery');
			const jquery = jqueryModule && (jqueryModule.default || jqueryModule);
			if (isFunction(jquery)) {
				const target = jquery(document);
				target.on('ajaxSend.ldpRequestFlow', (_event, xhr, settings = {}) => {
					const method = String(settings.type || settings.method || 'GET').toUpperCase();
					REQUEST_FLOW_AJAX_STATE.set(xhr, {
						event: beginRequestFlow(settings.url, {
							method,
							[REQUEST_FLOW_FETCH_META]: { callSite: '' },
						}, 'xmlhttprequest'),
						url: settings.url,
					});
				});
				target.on('ajaxComplete.ldpRequestFlow', (_event, xhr) => {
					const state = REQUEST_FLOW_AJAX_STATE.get(xhr);
					if (!state) return;
					REQUEST_FLOW_AJAX_STATE.delete(xhr);
					let headers = '';
					try { headers = xhr.getAllResponseHeaders(); } catch {}
					const finalUrl = finishResponseRequestFlow(
						state.event,
						xhr.responseURL || state.url,
						xhr.status,
						headers
					);
					captureHostTopicXhrResponse(state.event, xhr, finalUrl);
				});
				REQUEST_FLOW_AJAX_BOUND = true;
			}
		}

		if (REQUEST_FLOW_DETAILS_ACTIVE && !REQUEST_FLOW_RESOURCE_OBSERVER &&
				isFunction(window.PerformanceObserver)) {
			try {
				REQUEST_FLOW_RESOURCE_OBSERVER = new window.PerformanceObserver((list, _observer, options) => {
					list.getEntries().forEach(recordResourceRequestFlow);
					const dropped = Math.max(0, Number(options?.droppedEntriesCount) || 0);
					if (dropped) REQUEST_FLOW_RESOURCE_DROPS.push({ at: requestFlowNow(), count: dropped });
					pruneRequestFlowEvents();
				});
				REQUEST_FLOW_RESOURCE_OBSERVER.observe({
					type: 'resource',
					buffered: !REQUEST_FLOW_RESOURCE_BUFFERED,
				});
				REQUEST_FLOW_RESOURCE_BUFFERED = true;
			} catch {}
		}
		return REQUEST_FLOW_AJAX_BOUND;
	}

	function setRequestFlowDetailsActive(active) {
		REQUEST_FLOW_DETAILS_ACTIVE = active === true;
		if (REQUEST_FLOW_DETAILS_ACTIVE) {
			installRequestFlowInstrumentation();
			return;
		}
		if (REQUEST_FLOW_RESOURCE_OBSERVER) REQUEST_FLOW_RESOURCE_OBSERVER.disconnect();
		REQUEST_FLOW_RESOURCE_OBSERVER = null;
	}

	function trackedReaderFetch(input, init = {}) {
		const meta = init[REQUEST_FLOW_FETCH_META] || {};
		const trackedInit = {
			...init,
			[REQUEST_FLOW_FETCH_META]: { ...meta, source: 'reader' },
		};
		const event = beginRequestFlow(input, trackedInit, 'fetch');
		let request;
		try {
			request = window.fetch(input, init);
		} catch (error) {
			finishRequestFlow(event, { error: error?.name || 'fetch_error' });
			throw error;
		}
		return Promise.resolve(request).then((response) => {
			finishResponseRequestFlow(
				event,
				response?.url,
				response?.status,
				response?.headers
			);
			return response;
		}, (error) => {
			finishRequestFlow(event, { error: error?.name || 'fetch_error' });
			throw error;
		});
	}

	SHARED_REQUEST_COORDINATOR = createSharedRequestCoordinator();
	installRequestFlowInstrumentation();

	function resetReaderRateAfterChallenge() {
		if (ACTIVE_READER_REQUEST_SCHEDULER?.resetRateLimits) {
			void ACTIVE_READER_REQUEST_SCHEDULER.resetRateLimits();
			return true;
		}
		if (!SHARED_REQUEST_COORDINATOR || !SHARED_REQUEST_COORDINATOR.resetRateLimits) return false;
		void SHARED_REQUEST_COORDINATOR.resetRateLimits();
		return true;
	}
