			scheduleHostScrollbarSync();
			if (!embeddedMode()) return;
			const scrollTop = Math.max(0, Number(
				window.scrollY || document.scrollingElement?.scrollTop || 0,
			));
			if (hostTopJumping) {
				resetHostUpwardScroll(scrollTop);
				return;
			}
