		const colorPickerMoreButton = colorPickerPopover.querySelector('.ldp-color-picker-more');
		const colorPickerAdvanced = colorPickerPopover.querySelector('.ldp-color-picker-advanced');
		const colorPickerHueInput = colorPickerPopover.querySelector('.ldp-color-picker-hue');
		const colorPickerSaturationInput = colorPickerPopover.querySelector('.ldp-color-picker-saturation');
		const colorPickerBrightnessInput = colorPickerPopover.querySelector('.ldp-color-picker-brightness');
		const colorPickerHueValue = colorPickerPopover.querySelector('.ldp-color-picker-hue-value');
		const colorPickerSaturationValue = colorPickerPopover.querySelector('.ldp-color-picker-saturation-value');
		const colorPickerBrightnessValue = colorPickerPopover.querySelector('.ldp-color-picker-brightness-value');
		let activeColorInput = null;
