				const tab = event.target.closest('.ldp-bookmark-tab');
				if (!tab) return;
				bookmarkTabDrag = {
					tab,
					pointerId: event.pointerId,
					startX: event.clientX,
					startY: event.clientY,
					moved: false,
				};
				try { tab.setPointerCapture(event.pointerId); } catch {}
